import selfies as sf
from rdkit import Chem
from rdkit.Chem import rdMolDescriptors
r='[C][S][=Branch1][C][=O][=Branch1][C][=O][N][C][=C][C][=C][Branch2][Ring1][#Branch2][N][C][C][N][Branch1][S][C][=C][C][Branch1][=Branch1][N+1][=Branch1][C][=O][O-1][=C][C][=N][Ring1][=Branch2][C][C][Ring1][#C][C][=C][Ring2][Ring1][Branch1]'
p='[C][S][=Branch1][C][=O][=Branch1][C][=O][N][C][=C][C][=C][Branch2][Ring1][=Branch1][N][C][C][N][Branch1][N][C][=C][C][Branch1][C][N][=C][C][=N][Ring1][#Branch1][C][C][Ring1][=N][C][=C][Ring2][Ring1][Ring1]'
for label,x in [('reactant',r),('product',p)]:
    try:
        smi=sf.decoder(x)
        m=Chem.MolFromSmiles(smi)
        print(label,'SMILES:',smi)
        print(label,'canonical:',Chem.MolToSmiles(m) if m else None)
        print(label,'formula:',rdMolDescriptors.CalcMolFormula(m) if m else None,'atoms:',m.GetNumAtoms() if m else None,'bonds:',m.GetNumBonds() if m else None)
        if m:
            for a in m.GetAtoms(): print(a.GetIdx(),a.GetSymbol(),a.GetFormalCharge(),a.GetIsAromatic())
            print('BONDS',[(b.GetBeginAtomIdx(),b.GetEndAtomIdx(),str(b.GetBondType())) for b in m.GetBonds()])
    except Exception as e: print(label,'ERROR',repr(e))
